1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
72	const HIGH_ENCHANTMENT_THRESHOLD = 5;
73	const LOYALTY_DISCOUNT_RATE = 0.2;
74	const LOYALTY_YEARS_THRESHOLD = 2;
75	
76	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
77	
78	/** Rounds to whole G in the MHPCO's favour. */
79	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
80	
81	const groupByType = (items: Item[]): Map<string, Item[]> => {
82	  const groups = new Map<string, Item[]>();
83	  for (const item of items) {
84	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
85	  }
86	  return groups;
87	};
88	
89	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
90	
91	/**
92	 * Components are priced per group of alike items, because a building block of
93	 * exactly 3 alike components earns a special rate. Main items price per item.
94	 */
95	const basePremiumForGroup = (type: string, group: Item[]): number => {
96	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
97	    return BLOCK_BASE_PREMIUM;
98	  }
99	  return sum(group.map(basePremiumForItem));
100	};
101	
102	/** Item-specific surcharges apply to the affected item's own base premium. */
103	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
104	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
105	  {
106	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
107	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
108	  },
109	];
110	
111	const itemSurchargeTotalFor = (item: Item): number =>
112	  sum(
113	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
114	      ({ rate }) => basePremiumForItem(item) * rate,
115	    ),
116	  );
117	
118	/**
119	 * Policy-wide modifiers are rates on the UNMODIFIED policy base premium — not
120	 * on the running total, and not on the item surcharges. Charging 10 % of a
121	 * cursed sword's 150 G rather than of its 100 G base is the mistake this
122	 * indirection exists to prevent.
123	 */
124	const policyModifierTotalFor = (policyBasePremium: number, rates: number[]): number =>
125	  sum(rates.map((rate) => policyBasePremium * rate));
126	
127	/** Discounts are negative rates, so the policy modifiers stay a single sum. */
128	const policyModifierRatesFor = (customer: Customer): number[] => {
129	  const rates = [INITIAL_ASSESSMENT_SURCHARGE_RATE];
130	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) {
131	    rates.push(-LOYALTY_DISCOUNT_RATE);
132	  }
133	  return rates;
134	};
135	
136	const quotePremium = (items: Item[], customer: Customer): number => {
137	  const policyBasePremium = sum(
138	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
139	  );
140	  const itemSurchargeTotal = sum(items.map(itemSurchargeTotalFor));
141	  const policyModifierTotal = policyModifierTotalFor(
142	    policyBasePremium,
143	    policyModifierRatesFor(customer),
144	  );
145	  return roundUpToWholeG(
146	    policyBasePremium + itemSurchargeTotal + policyModifierTotal + PROCESSING_FEE,
147	  );
148	};
149	
150	export const runScenario = (scenario: Scenario): ScenarioResult => {
151	  return {
152	    results: scenario.steps.map((step) => ({
153	      premium: quotePremium((step as QuoteStep).items, scenario.customer),
154	    })),
155	  };
156	};
